    cout << "]\n";
}
static void print2D(const vector<vector<int>>& mat) {
    cout << "[";
    for(size_t i=0; i<mat.size(); ++i) {
        if(i>0) cout << ",";
        cout << "[";
        for(size_t j=0; j<mat[i].size(); ++j) { if(j>0) cout << ","; cout << mat[i][j]; }
        cout << "]";
    }
    cout << "]\n";
}
static void printStrVec(const vector<string>& v) {
    cout << "[";
    for(size_t i=0; i<v.size(); ++i) { if(i>0) cout << ","; cout << "\"" << v[i] << "\""; }
    cout << "]\n";
}

